{"implementation":"import math


def solve(case):
    if not isinstance(case, dict):
        raise ValueError("case must be an object")

    if "threshold" not in case or "calls" not in case:
        raise ValueError("case requires threshold and calls")

    threshold = case["threshold"]
    if type(threshold) not in (int, float) or not math.isfinite(threshold):
        raise ValueError("threshold must be a finite number")
    if threshold < 0:
        raise ValueError("threshold must be non-negative")

    calls = case["calls"]
    if not isinstance(calls, list):
        raise ValueError("calls must be a list")

    required = {
        "call_id",
        "loss_without_call",
        "loss_with_call",
        "prediction_tokens",
        "parseable",
    }
    seen_ids = set()
    validated = []

    for call in calls:
        if not isinstance(call, dict) or not required.issubset(call):
            raise ValueError("each call must contain all required fields")

        call_id = call["call_id"]
        if not isinstance(call_id, str) or not call_id or call_id in seen_ids:
            raise ValueError("call_id must be a unique non-empty string")
        seen_ids.add(call_id)

        loss_without = call["loss_without_call"]
        loss_with = call["loss_with_call"]
        for value in (loss_without, loss_with):
            if type(value) not in (int, float) or not math.isfinite(value) or value < 0:
                raise ValueError("losses must be finite non-negative numbers")

        prediction_tokens = call["prediction_tokens"]
        if type(prediction_tokens) is not int or prediction_tokens < 0:
            raise ValueError("prediction_tokens must be a non-negative integer")

        parseable = call["parseable"]
        if type(parseable) is not bool:
            raise ValueError("parseable must be a boolean")

        validated.append((call_id, float(loss_without), float(loss_with), prediction_tokens, parseable))

    diagnostics = []
    for call_id, loss_without, loss_with, prediction_tokens, parseable in validated:
        normalizer = max(1, prediction_tokens)
        normalized_weight = 1.0 / normalizer
        gain = loss_without - loss_with
        weighted_without = loss_without * normalized_weight
        weighted_with = loss_with * normalized_weight
        normalized_gain = gain * normalized_weight
        accepted = parseable and normalized_gain >= threshold

        diagnostics.append({
            "call_id": call_id,
            "parseable": parseable,
            "prediction_tokens": prediction_tokens,
            "normalized_weight": round(normalized_weight, 8),
            "weighted_loss_without_call": round(weighted_without, 8),
            "weighted_loss_with_call": round(weighted_with, 8),
            "gain": round(gain, 8),
            "normalized_gain": round(normalized_gain, 8),
            "accepted": accepted,
        })

    accepted_call_ids = [item["call_id"] for item in diagnostics if item["accepted"]]
    return {
        "accepted_call_ids": accepted_call_ids,
        "diagnostics": diagnostics,
    }
"}
